SELECT 'gongkao', '主宾关系', 'kp-xc-analogy-gram-so', CAST($${"type":"doc","content":[{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"主宾关系"}]},{"type":"highlightBlock","attrs":{"backgroundColor":"#fffbeb","borderColor":"#f59e0b","icon":"💡"},"content":[{"type":"paragraph","content":[{"type":"text","text":"核心结论：","marks":[{"type":"bold"}]},{"type":"text","text":"主语 + 宾语的关系（省略谓语）。如「学生:教室」（学生在教室）「司机:汽车」（司机开汽车）。约 37 题。"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"一、题型识别"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"两个词之间需要补充一个动词才能成句"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"常见于：人与工具、人与场所、人与对象"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"二、与其他语法关系的区分"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"主宾 vs 动宾：主宾省略了动词，动宾有动词"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"主宾 vs 对应关系：主宾是语法结构，对应是语义关系"}]}]}]},{"type":"highlightBlock","attrs":{"backgroundColor":"#eff6ff","borderColor":"#3b82f6","icon":"📊"},"content":[{"type":"paragraph","content":[{"type":"text","text":"刷题建议：","marks":[{"type":"bold"}]},{"type":"text","text":"主宾关系考频低，关键是补充动词判断关系。"}]}]}]}$$ AS jsonb), NULL, '类比推理-语法关系-主宾关系：主语与宾语的关系。', category_node.id, CAST('["类比推理", "语法关系", "主宾关系"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_judgement_analogy_grammar_subject_object", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
